class Solution {
    public String abbreviateProduct(int left, int right) {
        int c2 = 0, c5 = 0;
        for (int i = left; i <= right; i++) {
            int x = i;
            while (x % 2 == 0) { x /= 2; c2++; }
            while (x % 5 == 0) { x /= 5; c5++; }
        }
        int C = Math.min(c2, c5);
        int rem2 = C, rem5 = C;
        long mod = 1;
        double hi = 1;
        long exact = 1;
        boolean big = false;
        for (int i = left; i <= right; i++) {
            int x = i;
            while (x % 2 == 0 && rem2 > 0) { x /= 2; rem2--; }
            while (x % 5 == 0 && rem5 > 0) { x /= 5; rem5--; }
            mod = mod * x % 100000L;
            hi *= x;
            while (hi >= 1e10) hi /= 10;
            if (!big) {
                exact *= x;
                if (exact >= 10000000000L) big = true;
            }
        }
        if (!big) {
            return exact + "e" + C;
        }
        while (hi >= 1e5) hi /= 10;
        long prefix = (long) hi;
        return prefix + "..." + String.format("%05d", mod) + "e" + C;
    }
}
