I'll use a BFS level by level. For each node, I check whether its two children are exactly x and y, which would make them siblings and therefore not cousins. Otherwise, I record whether x or y appears at the current level. If both appear on the same level and are not siblings, they are cousins.

```java
import java.util.*;

class Solution {
    public boolean isCousins(TreeNode root, int x, int y) {
        Queue<TreeNode> q = new LinkedList<>();
        q.add(root);
        while (!q.isEmpty()) {
            int size = q.size();
            boolean fx = false, fy = false;
            for (int i = 0; i < size; i++) {
                TreeNode n = q.poll();
                if (n.val == x) fx = true;
                if (n.val == y) fy = true;
                if (n.left != null && n.right != null) {
                    if ((n.left.val == x && n.right.val == y) || (n.left.val == y && n.right.val == x)) {
                        return false;
                    }
                }
                if (n.left != null) q.add(n.left);
                if (n.right != null) q.add(n.right);
            }
            if (fx && fy) return true;
            if (fx || fy) return false;
        }
        return false;
    }
}
```

