class Solution {
    public int maxEqualFreq(int[] nums) {
        int[] cnt = new int[100002];
        int[] freq = new int[100002];
        int maxF = 0;
        int ans = 0;
        for (int idx = 0; idx < nums.length; idx++) {
            int x = nums[idx];
            int i = idx + 1;
            if (cnt[x] > 0) freq[cnt[x]]--;
            cnt[x]++;
            freq[cnt[x]]++;
            if (cnt[x] > maxF) maxF = cnt[x];
            boolean ok = false;
            if (maxF == 1) ok = true;
            else if (freq[maxF] * maxF + 1 == i && freq[1] == 1) ok = true;
            else if (freq[maxF] == 1 && freq[maxF - 1] * (maxF - 1) + maxF == i) ok = true;
            if (ok) ans = i;
        }
        return ans;
    }
}
