        long sum = 0;
        long ans = 0;
        for (int r = 0; r < n; r++) {
            sum += fruits[r][1];
            while (l <= r) {
                int L = fruits[l][0];
                int R = fruits[r][0];
                int cost = (R - L) + Math.min(Math.abs(startPos - L), Math.abs(startPos - R));
