```java
class Solution {
    public int minOperations(String s) {
        int c = 0;
        int n = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch != '0' && ch != '1') continue;
            int expected = n % 2; // pattern starting with '0'
            if (ch - '0' != expected) c++;
            n++;
        }
        return Math.min(c, n - c);
    }
}
