import java.util.HashMap;

class Solution {
    private HashMap<Integer, Integer> memo = new HashMap<>();

    public int minDays(int n) {
        if (n <= 1) return n;
        Integer c = memo.get(n);
        if (c != null) return c;
        int res = 1 + Math.min(n % 2 + minDays(n / 2), n % 3 + minDays(n / 3));
        memo.put(n, res);
        return res;
    }
}
