import java.util.*;

class Solution {
    public double[] medianSlidingWindow(int[] nums, int k) {
        final int[] a = nums;
        Comparator<Integer> cmp = (x, y) -> a[x] != a[y] ? Integer.compare(a[x], a[y]) : Integer.compare(x, y);
        TreeSet<Integer> lo = new TreeSet<>(cmp);
        TreeSet<Integer> hi = new TreeSet<>(cmp);
        int n = nums.length;
        double[] res = new double[n - k + 1];
        for (int i = 0; i < n; i++) {
            if (i >= k) {
                int r = i - k;
                if (lo.contains(r)) lo.remove(r);
                else hi.remove(r);
                rebalance(lo, hi);
            }
            if (lo.isEmpty() || cmp.compare(i, lo.last()) <= 0) lo.add(i);
            else hi.add(i);
            rebalance(lo, hi);
            if (i >= k - 1) {
                if (k % 2 == 1) res[i - k + 1] = nums[lo.last()];
                else res[i - k + 1] = ((double) nums[lo.last()] + (double) nums[hi.first()]) / 2.0;
            }
        }
        return res;
    }

