class Solution {
    public boolean validateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int[] indeg = new int[n];
        for (int i = 0; i < n; i++) {
            if (leftChild[i] != -1) {
                if (++indeg[leftChild[i]] > 1) return false;
            }
            if (rightChild[i] != -1) {
                if (++indeg[rightChild[i]] > 1) return false;
            }
        }
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (indeg[i] == 0) {
                if (root != -1) return false;
                root = i;
            }
        }
        if (root == -1) return false;
        int[] queue = new int[n];
        int head = 0, tail = 0;
        queue[tail++] = root;
        int count = 0;
