```java
class Solution {
    long[] w = new long[26];
    int[] letters;
    boolean[] lead = new boolean[26];
    int n;

    public boolean isSolvable(String[] words, String result) {
        boolean[] present = new boolean[26];
        for (String s : words) {
            s = s.trim();
            long p = 1;
            for (int i = s.length() - 1; i >= 0; i--) {
                int c = s.charAt(i) - 'A';
                w[c] += p;
                p *= 10;
                present[c] = true;
            }
            if (s.length() > 1) lead[s.charAt(0) - 'A'] = true;
        }
        String s = result.trim();
        long p = 1;
        for (int i = s.length() - 1; i >= 0; i--) {
            int c = s.charAt(i) - 'A';
            w[c] -= p;
            p *= 10;
            present[c] = true;
        }
        if (s.length() > 1) lead[s.charAt(0) - 'A'] = true;
        int cnt = 0;
        for (int i = 0; i < 26; i++) if (present[i]) cnt++;
        letters = new int[cnt];
        int k = 0;
        for (int i = 0; i < 26; i++) if (present[i]) letters[k++] = i;
        n = cnt;
        return dfs(0, 0, 0);
    }

    boolean dfs(int idx, long sum, int mask) {
        if (idx == n) return sum == 0;
        int c = letters[idx];
        for (int d = 0; d < 10; d++) {
            if ((mask & (1 << d)) != 0) continue;
            if (d == 0 && lead[c]) continue;
            if (dfs(idx + 1, sum + w[c] * d, mask | (1 << d))) return true;
        }
        return false;
    }
}
